mapper.sql:
WHERE geom && ST_MakeEnvelope(#{bbox.minLng}, #{bbox.minLat}, #{bbox.maxLng}, #{bbox.maxLat}, 4326)

    AND deal_type = #{filter.dealType}
    AND property_type = #{filter.propertyType}



                AND deposit >= #{filter.priceMin}
                AND deposit <= #{filter.priceMax}


                AND deal_amount >= #{filter.priceMin}
                AND deal_amount <= #{filter.priceMax}


                AND COALESCE(deal_amount, deposit) >= #{filter.priceMin}
                AND COALESCE(deal_amount, deposit) <= #{filter.priceMax}
